from __future__ import annotations

from unittest.mock import patch

from app.core.config import Settings
from app.libs.identity.service import FirebaseIdentityService
from tests.libs.identity.conftest import FakeAuthModule


def _service(settings: Settings | None = None) -> FirebaseIdentityService:
    return FirebaseIdentityService(settings or Settings(firebase_auth_disabled=False))


# --- Positive --------------------------------------------------------------------


def test_create_user_passes_no_password_to_the_sdk_by_default():
    fake_auth = FakeAuthModule()
    svc = _service()
    with patch("app.libs.identity.service.auth", fake_auth), patch(
        "app.libs.identity.service._init_firebase"
    ):
        svc.create_user("new@example.com")
    assert fake_auth.create_user_calls == ["new@example.com"]
    assert fake_auth.create_user_kwargs[-1].get("password") is None


# --- Negative: dev-bypass path unaffected --------------------------------------------


def test_dev_bypass_path_never_calls_the_real_sdk_at_all():
    fake_auth = FakeAuthModule()
    svc = _service(Settings(firebase_auth_disabled=True))
    with patch("app.libs.identity.service.auth", fake_auth):
        uid = svc.create_user("dev@example.com")
    assert uid == "dev-dev@example.com"
    assert fake_auth.create_user_calls == []


